CREATE DATABASE IF NOT EXISTS ghost_worker_db CHARACTER SET utf8mb4; USE ghost_worker_db;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(120) NOT NULL,username VARCHAR(60) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','hr','payroll','auditor') NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS employees(id INT AUTO_INCREMENT PRIMARY KEY,employee_no VARCHAR(40) UNIQUE NOT NULL,full_name VARCHAR(150) NOT NULL,national_id VARCHAR(60),department VARCHAR(100),job_title VARCHAR(100),employment_status ENUM('active','inactive','terminated','retired') DEFAULT 'active',appointment_date DATE,bank_account VARCHAR(80),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS payroll(id INT AUTO_INCREMENT PRIMARY KEY,employee_id INT NULL,employee_no VARCHAR(40) NOT NULL,pay_period VARCHAR(7) NOT NULL,gross_amount DECIMAL(12,2) NOT NULL,payment_reference VARCHAR(100),payment_date DATE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(employee_no),FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS investigations(id INT AUTO_INCREMENT PRIMARY KEY,payroll_id INT NOT NULL,employee_id INT NULL,reason VARCHAR(255) NOT NULL,status ENUM('pending','under_review','cleared','confirmed_issue') DEFAULT 'pending',review_notes TEXT,reviewed_by INT NULL,reviewed_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY one_flag(payroll_id),FOREIGN KEY(payroll_id) REFERENCES payroll(id) ON DELETE CASCADE,FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE SET NULL,FOREIGN KEY(reviewed_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS audit_logs(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,action VARCHAR(100),details TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
